// Calculate last week's date
const now = new Date();
const lastWeek = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);
const lastWeekDate = lastWeek.toISOString();

return [{
  json: {
    lastWeekDate: lastWeekDate,
    currentDate: now.toISOString()
  }
}];

// Aggregate data from GitHub
const commits = $input.all()[0]?.json || [];
const issues = $input.all()[1]?.json || [];
const prs = $input.all()[2]?.json || [];

// Filter PRs merged in last week
const mergedPRs = prs.filter(pr => pr.merged_at && new Date(pr.merged_at) > new Date($json.lastWeekDate));

// Format data for Claude
const summaryData = {
  commits: {
    count: commits.length,
    items: commits.slice(0, 10).map(c => ({
      message: c.commit?.message?.split('\n')[0] || 'No message',
      author: c.commit?.author?.name || 'Unknown',
      date: c.commit?.author?.date
    }))
  },
  issues: {
    count: issues.length,
    items: issues.slice(0, 10).map(i => ({
      title: i.title,
      number: i.number,
      closed_at: i.closed_at
    }))
  },
  pullRequests: {
    count: mergedPRs.length,
    items: mergedPRs.slice(0, 10).map(p => ({
      title: p.title,
      number: p.number,
      merged_at: p.merged_at
    }))
  },
  weekRange: {
    start: $json.lastWeekDate,
    end: $json.currentDate
  }
};

return [{ json: summaryData }];

